on delay() {\n                    this.classList.add(\"animate--to_stock\")\n                }\n\n                time = i * 150;\n                setTimeout(delay.bind(animate.items[i]), time)\n            }\n            else {\n                animate.items[i].classList.add(\"animate--to_stock\");\n            }\n        }\n    }\n    document.addEventListener(\"DOMContentLoaded\", function () {\n        animation();\n    });\n</script>\n\n<script src=\"https://cdnjs.cloudflare.com/ajax/libs/gsap/1.19.1/TweenMax.min.js\"></script>\n\n<script>\n    //animation square items\n    var serviceItems = document.querySelectorAll(\".service--title_up\");\n    for (var q = 0; q < serviceItems.length; q++) {\n        var serviceItem = serviceItems[q];\n        serviceItem.addEventListener(\"mouseenter\", function () {\n            titleUp(this, true);\n        })\n        serviceItem.addEventListener(\"mouseleave\", function () {\n            titleUp(this, false);\n        })\n    }\n\n    function titleUp(service, state) {\n        var $title = service.querySelector(\".service__title\");\n        var $img = service.querySelector(\".service__img\");\n        var $text = service.querySelector(\".service__text\");\n        var $overflow = service.querySelector(\".service__overflow\");\n\n        if (state) {\n            TweenLite.to($title, .3, {minHeight: \"100%\"});\n            TweenLite.to($img, .2, {'-webkit-filter': 'blur(10px)'});\n            TweenLite.to($text, .3, {delay: 0, ease: Back.easeOut.config(0), bottom: 0, opacity: 1});\n            TweenLite.to($overflow, .3, {\n                backgroundColor: \"rgba(225, 10, 19, .7)\",\n                backgroundImage: 'url(\"<?= SITE_TEMPLATE_PATH?>/img/main_pattern--5.png\")'\n            });\n\n        } else {\n            TweenLite.to($title, .3, {minHeight: \"0\"});\n            TweenLite.to($img, .2, {'-webkit-filter': 'blur(0px)'});\n            TweenLite.to($text, .3, {delay: 0, bottom: \"-100%\", opacity: 0});\n            TweenLite.to($overflow, .3, {\n                backgroundColor: \"rgba(225, 10, 19, 0)\",\n                backgroundImage: \"linear-gradient(to bottom, rgba(255, 255, 255, 0.0) 4%, rgba(0, 0, 0, 0.3))\"\n            });\n        }\n    }\n</script>\n<script>\n    //accordions toggle\n    document.querySelectorAll(\".accordion__label\").forEach(function (elem) {\n        elem.addEventListener(\"click\", function () {\n            toggleBox(this);\n        })\n    })\n\n    function toggleBox(box) {\n        var boxBody = box.parentNode.querySelector(\".accordion__body\");\n        var boxBtn = box.querySelector(\".accordion__btn\");\n        var boxLabel = box.parentNode.querySelector(\".accordion__label\");\n        var boxItem = box.parentNode;\n\n        if (parseInt(boxBody.style.maxHeight) == 0 || isNaN(parseInt(boxBody.style.maxHeight))) {\n            TweenLite.to(boxBody, 0, {maxHeight: boxBody.scrollHeight + 40});\n            TweenLite.to(boxBtn, 0, {rotation: \"0_short\", ease: Back.easeOut.config(1)});\n            TweenLite.to(boxLabel, 0, {backgroundColor: \"transparent\", color: \"black\"});\n            TweenLite.to(boxItem, 0, {boxShadow: \"none\"});\n        }\n        else {\n            TweenLite.to(boxBody, 0, {clearProps: \"all\"});\n            TweenLite.to(boxBtn, 0, {clearProps: \"all\"});\n            TweenLite.to(boxLabel, 0, {clearProps: \"all\"});\n            TweenLite.to(boxItem, 0, {clearProps: \"all\"});\n        }\n    }\n</script>\n\n\n<!-- animation index parallax-->\n<script>\n\t(function indexParallax() {\n        var $paralaxElem = document.querySelector('.section--service_index');\n\t\tif($paralaxElem){\n        var style = window.getComputedStyle($paralaxElem, null);\n        $paralaxElem.startHeight = parseInt(style.getPropertyValue(\"height\"));\n\n        window.addEventListener('scroll', function () {\n            var scroll_perc = parseInt(window.pageYOffset);\n\n\t\t\tfunction setTranslate(xPos, yPos, elem)